-- Preserve the deployed read-model contract while removing its unused local variable.
create or replace function private.analytics_interviews(p_slug text,p_filters jsonb default '{}',p_limit integer default 12) returns jsonb language plpgsql security definer set search_path='' as $$
declare c jsonb;mocks jsonb;session_ids uuid[];mock_state text:='empty';phases jsonb;behavioral jsonb;oa jsonb;coverage jsonb;begin
 c:=private.analytics_context(p_slug,p_filters);if p_limit not between 1 and 100 then raise exception 'Invalid interview evidence limit' using errcode='22023';end if;
 select coalesce(array_agg(distinct q.session_id),'{}'::uuid[]) into session_ids from private.analytics_attempt_rows(c) q where not q.invalid and q.at>=(c->>'fromAt')::timestamptz;
 begin
 with raw_candidates as materialized(select m.*,s.started_at execution_started_at,s.completed_at ended_at,s.accumulated_pause_ms,s.target_duration_seconds,s.status execution_status from public.mock_sessions m join public.execution_sessions s on s.id=m.execution_session_id and s.workspace_id=m.workspace_id and s.user_id=m.user_id
 where m.workspace_id=(c->'workspace'->>'id')::uuid and m.user_id=(select auth.uid()) and s.status in ('completed','expired') and s.completion_reason not in ('abandoned','session_invalidated') and s.completed_at>=(c->>'fromAt')::timestamptz and s.completed_at<(c->>'toAt')::timestamptz
 and (coalesce(p_filters->>'mode','all')='all' or s.mode=p_filters->>'mode') and (coalesce(p_filters->>'sessionType','all') in ('all','mock'))
 and s.id=any(session_ids)
 order by s.completed_at desc,m.id desc),
 candidates as materialized(select * from(select distinct on(execution_session_id) * from raw_candidates order by execution_session_id,created_at,id)x order by ended_at desc,id limit p_limit),
 item_groups as(select m.id,count(i.id) total,count(i.id) filter(where i.status='answered') answered,count(lb.item_id) filter(where lb.submitted_at is not null and lb.correct is not null) objective_n,count(lb.item_id) filter(where lb.submitted_at is not null and lb.correct) correct,
 coalesce(jsonb_agg(jsonb_build_object('difficulty',i.difficulty,'type',coalesce(mi.source_type,'custom')) order by i.position),'[]') profile
 from candidates m join public.execution_session_items i on i.session_id=m.execution_session_id and i.workspace_id=m.workspace_id and i.user_id=m.user_id left join lateral(select mm.source_type from public.mock_session_items mm where mm.execution_item_id=i.id and mm.mock_session_id=m.id and mm.workspace_id=m.workspace_id and mm.user_id=m.user_id order by mm.sort_order,mm.id limit 1) mi on true left join public.learning_execution_bindings lb on lb.item_id=i.id group by m.id)
 select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'executionId',m.execution_session_id,'title',m.title,'mode',m.mode,'at',m.ended_at,'blueprintId',m.blueprint_id,'blueprintVersion',m.blueprint_version,'policyVersion',m.evaluation_policy_version,
 'family',coalesce(m.blueprint_id,'custom')||' · v'||m.blueprint_version||' · '||m.mode||' · '||substr(md5(g.profile::text||m.policy_snapshot::text||m.evaluation_policy_version),1,8),
 'questionCount',g.total,'answered',g.answered,'durationMs',greatest(0,floor(extract(epoch from m.ended_at-m.execution_started_at)*1000)-m.accumulated_pause_ms),'targetMs',m.target_duration_seconds::bigint*1000,'objectiveN',g.objective_n,'correct',g.correct,'objectiveAccuracy',case when g.objective_n>=5 then g.correct::numeric/g.objective_n end,
 'facets',(select jsonb_agg(jsonb_build_object('dimension',d.dimension,'status',case when mr.review_snapshot->'facets'->d.dimension->>'status' in ('stable','needs_attention','developing','strong','not_evaluated','no_recent_evidence','overestimated') then mr.review_snapshot->'facets'->d.dimension->>'status' else 'not_evaluated' end,'provenance','self_reported','n',case when mr.review_snapshot->'facets'->d.dimension->>'status' in ('stable','needs_attention','developing','strong','overestimated') then 1 else 0 end)) from(values('problem_solving'),('correctness'),('complexity'),('communication'),('testing'),('speed'),('confidence'))d(dimension))) order by m.ended_at desc,m.id) ,'[]') into mocks from candidates m join item_groups g on g.id=m.id left join public.mock_reviews mr on mr.mock_session_id=m.id and mr.workspace_id=m.workspace_id and mr.user_id=m.user_id;
 if jsonb_array_length(mocks)>0 then mock_state:='ready';end if;
 exception when undefined_table then mocks:='[]';mock_state:='unavailable';end;
 -- Only sessions with recorded phase transitions are eligible for phase allocation.
 with eligible_sessions as materialized(select distinct s.id,s.started_at,s.completed_at,greatest(0,floor(extract(epoch from s.completed_at-s.started_at)*1000)-s.accumulated_pause_ms)::bigint total_ms from public.execution_sessions s where s.id=any(session_ids) and s.workspace_id=(c->'workspace'->>'id')::uuid and s.user_id=(select auth.uid()) and s.mode='interview' and s.completed_at>=(c->>'fromAt')::timestamptz and exists(select 1 from public.execution_events e where e.session_id=s.id and e.event_type='phase_changed') order by s.completed_at desc limit 200),
 events as(select s.id,'understand'::text phase,0::bigint elapsed_ms,s.started_at created_at,0 priority from eligible_sessions s union all select s.id,e.phase,e.elapsed_ms,e.created_at,1 from eligible_sessions s join public.execution_events e on e.session_id=s.id where e.event_type='phase_changed' and e.phase is not null),
 flows as(select e.*,greatest(0,least(s.total_ms,lead(e.elapsed_ms,1,s.total_ms) over(partition by e.id order by e.elapsed_ms,e.created_at,e.priority))-least(s.total_ms,e.elapsed_ms)) duration_ms from events e join eligible_sessions s on s.id=e.id)
 select coalesce(jsonb_agg(jsonb_build_object('phase',x.phase,'durationMs',x.duration_ms,'sessions',x.sessions) order by case x.phase when 'understand' then 1 when 'clarify' then 2 when 'approach' then 3 when 'implement' then 4 when 'test' then 5 else 6 end),'[]') into phases from(select phase,sum(duration_ms) duration_ms,count(distinct id) sessions from flows group by phase)x;
 begin coverage:=private.behavioral_coverage(p_slug);exception when others then coverage:=null;end;
 with b as materialized(select bp.story_id,s.title,bp.cue_level,bp.confidence,bp.clarity,bp.retold,q.duration_ms,e.completed_at as at from public.behavioral_practice_bindings bp join public.star_stories s on s.id=bp.story_id join public.question_attempts q on q.item_id=bp.item_id join public.execution_sessions e on e.id=bp.session_id
 where bp.workspace_id=(c->'workspace'->>'id')::uuid and bp.user_id=(select auth.uid()) and bp.committed and q.reflection_status='completed' and q.duration_ms>=15000 and e.status='completed' and e.completion_reason not in ('session_invalidated','abandoned') and e.completed_at>=(c->>'fromAt')::timestamptz and e.completed_at<(c->>'toAt')::timestamptz
 and coalesce(p_filters->>'track','all') in ('all','behavioral') and coalesce(p_filters->>'topic','all')='all' and coalesce(p_filters->>'difficulty','all') in ('all','unspecified') and coalesce(p_filters->>'mode','all') in ('all','practice') and coalesce(p_filters->>'questionType','all') in ('all','behavioral') and (coalesce(p_filters->>'sessionType','all')='all' or case when exists(select 1 from public.revision_execution_links rsi where rsi.item_id=q.item_id) then 'revision' else 'initial' end=p_filters->>'sessionType'))
 select jsonb_build_object('n',count(*),'stories',count(distinct story_id),'noCue',count(*) filter(where cue_level=0),'outline',count(*) filter(where cue_level=1),'fullStory',count(*) filter(where cue_level=2),'observations',coalesce((select jsonb_agg(jsonb_build_object('at',x.at,'storyId',x.story_id,'title',x.title,'cueLevel',x.cue_level,'confidence',x.confidence,'clarity',x.clarity,'durationMs',x.duration_ms,'retold',x.retold) order by x.at) from(select * from b order by at desc limit 50)x),'[]'),'coverage',coverage) into behavioral from b;
 with sessions as materialized(select s.id from public.execution_sessions s where s.workspace_id=(c->'workspace'->>'id')::uuid and s.user_id=(select auth.uid()) and s.mode='oa' and s.status in ('completed','expired') and s.completion_reason<>'session_invalidated' and s.completed_at>=(c->>'fromAt')::timestamptz and s.completed_at<(c->>'toAt')::timestamptz and s.id=any(session_ids)),
 items as(select i.*,lb.submitted_at,lb.correct from sessions s join public.execution_session_items i on i.session_id=s.id left join public.learning_execution_bindings lb on lb.item_id=i.id)
 select jsonb_build_object('n',(select count(*) from sessions),'complete',(select count(*) from sessions s where not exists(select 1 from items i where i.session_id=s.id and i.status<>'answered')),'answered',count(*) filter(where status='answered'),'unanswered',count(*) filter(where status<>'answered'),'objectiveN',count(*) filter(where submitted_at is not null and correct is not null),'correct',count(*) filter(where submitted_at is not null and correct),'accuracy',case when count(*) filter(where submitted_at is not null and correct is not null)>=5 then count(*) filter(where submitted_at is not null and correct)::numeric/nullif(count(*) filter(where submitted_at is not null and correct is not null),0) end) into oa from items;
 return jsonb_build_object('context',c-'filters','mocks',mocks,'mockState',mock_state,'mockLimit',p_limit,'phases',phases,'behavioral',behavioral,'oa',oa,'readiness',jsonb_build_object('state','unavailable','reason','There is no authoritative Readiness engine or versioned readiness snapshots in this repository. Mastery and behavioral coverage remain separate evidence sources.'),'tracker',jsonb_build_object('state','unavailable','reason','Interview tracking and project evaluation are not connected to an authoritative evidence source.'));
end $$;
